describe('Error Page Display on 500 Server Error', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display error page when server returns 500 status', () => {
    // Intercept the API call and simulate a 500 error response
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('apiError');

    // Attempt to load data
    cy.get('[data-testid="load-data-button"]').click();

    // Wait for the error response
    cy.wait('@apiError');

    // Verify error page is displayed
    cy.get('[data-testid="error-page"]').should('be.visible');
    cy.get('[data-testid="error-title"]').should('contain', 'Something went wrong');
    cy.get('[data-testid="error-message"]').should('contain', 'Internal Server Error');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Verify navigation back button is available
    cy.get('[data-testid="back-to-home-button"]').should('be.visible');
  });

  it('should handle 500 error gracefully and not crash the app', () => {
    // Intercept the API call and simulate a 500 error response
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('apiError');

    // Attempt to load data
    cy.get('[data-testid="load-data-button"]').click();

    // Wait for the error response
    cy.wait('@apiError');

    // Verify error page is displayed
    cy.get('[data-testid="error-page"]').should('be.visible');

    // Verify user can navigate back to previous page
    cy.get('[data-testid="back-to-home-button"]').click();

    // Verify app is still responsive and user can interact with other elements
    cy.get('[data-testid="dashboard-section"]').should('be.visible');
    cy.get('[data-testid="dashboard-header"]').should('contain', 'Dashboard');

    // Verify error message is cleared after retry
    cy.get('[data-testid="retry-button"]').click();
    cy.get('[data-testid="error-page"]').should('not.exist');
    cy.get('[data-testid="dashboard-section"]').should('be.visible');
  });
});
